use serde::{Deserialize, Serialize};
use std::collections::HashMap;

# [doc = " Types that can be decoded from a hex string."] # [doc = ""] # [doc = " This trait is implemented for `Vec<u8>` and small `u8`-arrays."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```"] # [doc = " use core::str;"] # [doc = " use hex::FromHex;"] # [doc = ""] # [doc = " let buffer = <[u8; 12]>::from_hex(\"48656c6c6f20776f726c6421\")?;"] # [doc = " let string = str::from_utf8(&buffer).expect(\"invalid buffer length\");"] # [doc = ""] # [doc = " println!(\"{}\", string); // prints \"Hello world!\""] # [doc = " # assert_eq!(\"Hello world!\", string);"] # [doc = " # Ok::<(), hex::FromHexError>(())"] # [doc = " ```"] pub trait FromHex : Sized { type Error ; # [doc = " Creates an instance of type `Self` from the given hex string, or fails"] # [doc = " with a custom error type."] # [doc = ""] # [doc = " Both, upper and lower case characters are valid and can even be"] # [doc = " mixed (e.g. `f9b4ca`, `F9B4CA` and `f9B4Ca` are all valid strings)."] fn from_hex < T : AsRef < [u8] > > (hex : T) -> Result < Self , Self :: Error > ; }